{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "Anemoside B4, a triterpenoid saponin with multiple sugar residues, was detected in rat brain at 187.2 ng/g after oral administration, directly demonstrating that large polar saponins can achieve CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Ciwujianoside C3, another triterpenoid saponin, was detected in the cerebral cortex of mice after oral administration, supporting CNS penetration for this structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Hydroxysafflor yellow A, a highly polar C-glycoside, reached 1026 ng/g in rat brain, showing that high polarity and large size do not preclude meaningful brain exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "A glucose-conjugated compound crossed the BBB in rats via GLUT1-mediated transport, indicating that active uptake mechanisms can overcome poor passive permeability for glycosides.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Nelarabine, a polar nucleoside analog, showed excellent CSF penetration in non-human primates, providing additional evidence that polar glycoside-like molecules can access the CNS.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Despite unfavorable passive physicochemical properties, multiple direct experimental studies on structurally related triterpenoid saponins and polar glycosides demonstrate measurable brain/CSF exposure, supporting meaningful CNS access for this saponin-like query.",
  "evidence_gaps": [
    "No direct quantitative brain-to-plasma ratio or unbound brain concentration is available for the exact query molecule.",
    "Efflux transporter liability for the query is inferred from physicochemical properties but not experimentally confirmed.",
    "Brain concentrations in the analogue studies are low (ng/g range), so the therapeutic meaningfulness of the exposure is uncertain."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

